globalThis.KENGURU_LEGACY = [[2015,"3–4 классы",[[841,160,"Незнайка писал слово КЕНГУРУ. У него получилось: Сколько букв он написал неправильно?",{},"D","Перевёрнутые буквы",[["Сверь с образцом","Сравни буквы по одной со словом КЕНГУРУ. К, Н и первая У стоят правильно."],["Отметь ошибки","Буквы Е, Г, Р и последняя У повёрнуты или отражены. Всего четыре ошибки."]],""],[841,70,"Чему равна сумма двадцати сотен и пятнадцати?",{},"C","Двадцать сотен",[["Переведи сотни","Одна сотня — 100, а двадцать сотен — 20 × 100 = 2000."],["Прибавь пятнадцать","2000 + 15 = 2015."]],""],[841,229,"Индеец Белый Орёл живет в вигваме, на котором треугольников и квадратиков нарисовано поровну. На каком из рисунков изображён его вигвам?",{},"E","Вигвам Белого Орла",[["Раздели узоры","При подсчёте бери только нарисованные треугольники и квадратики. Дверь и контур вигвама в счёт не идут."],["Сравни числа","На вигваме Д три треугольника и три квадратика. Их поровну."]],""],[841,183,"",{"0":[51.8,35.3,31.4,26.3],"1":[51.8,63.5,31.1,26.3],"2":[51.8,91.7,31.4,26.3],"3":[51.7,119.9,28.4,26.3],"4":[51.7,149.4,31.7,26.3]},"C","Дюжина и сутки",[["Найди три раза по четыре","Это задача 4, а 3 × 4 = 12. Дюжина, число месяцев и число подвигов Геракла тоже равны 12."],["Проверь сутки","В сутках 24 часа. Значит, подходит вариант В."]],""],[841,242,"(В) число часов в сутках (Г) утроенный номер этой задачи (Д) число подвигов Геракла 5. На рисунке изображён пруд и несколько лягушек. Сколько из этих лягушек сидят в пруду?",{},"B","Лягушки в пруду",[["Проследи берег","Веди пальцем по линии берега. У пруда есть узкие изгибы, поэтому две лягушки рядом на рисунке могут оказаться по разные стороны линии."],["Отметь сидящих в воде","В воде сидят верхняя левая лягушка, две лягушки в изгибах ближе к середине, одна на верхнем краю правого изгиба и две внизу. Всего их шесть."]],""],[841,97,"В числе 2015 четыре цифры. Произведение двух бóльших цифр поделили на сумму двух меньших. Что получилось?",{"0":[51.8,63.6,31.4,26.3],"1":[201.8,63.6,31.1,26.3],"2":[351.7,63.6,31.4,26.3],"3":[501.6,63.6,28.4,26.3],"4":[651.5,63.6,31.7,26.3]},"D","Цифры числа 2015",[["Выбери пары","Две бо́льшие цифры — 5 и 2, их произведение равно 10."],["Посчитай результат","Две меньшие цифры — 0 и 1, их сумма равна 1. Теперь 10 : 1 = 10."]],""],[848,234,"Петя катается на велосипеде по дорожкам, изображённым на рисунке. Он стартует из точки О в направлении, указанном стрелкой. На первом перекрёстке Петя поворачивает направо, на втором — налево, потом опять направо, потом опять налево, и так далее. В какой точке он не может оказаться?",{"0":[51.7,199.4,31.4,26.3],"1":[161.6,199.4,31.1,26.3],"2":[278.3,199.4,31.4,26.3],"3":[395,199.4,28.4,26.3],"4":[511.5,199.4,31.7,26.3]},"A","Велосипедный маршрут",[["Пройди первые повороты","Из О Петя едет к Г. Правый поворот ведёт его через В к Б, а левый в точке Б — обратно к Г по верхней стороне квадрата."],["Замкни маршрут","В Г Петя поворачивает направо к Д, а в Д — налево через О. Он возвращается в исходную точку в том же направлении и дальше повторяет путь. В точку А он не заезжает."]],""],[848,149,"Аня отметила на прямой линии 5 красных точек. В каждый промежуток между красными точками она поставила синюю точку, а потом в каждый промежуток между красной и синей точками — зелёную точку. Сколько всего точек получилось?",{"0":[51.7,115.1,31.4,26.3],"1":[201.7,115.1,31.1,26.3],"2":[351.6,115.1,31.4,26.3],"3":[501.5,115.1,28.4,26.3],"4":[651.3,115.1,31.7,26.3]},"C","Разноцветные точки",[["Найди синие точки","Между пятью последовательными красными точками четыре промежутка. В каждом появится одна синяя точка."],["Добавь зелёные","Каждая синяя делит один исходный промежуток на два. Значит, зелёных точек 8, а всего 5 + 4 + 8 = 17."]],""],[848,149,"Аня, Боря, Вася, Гриша и Дима написали на доске числа 1, 3, 4, 6 и 8, каждый по одному числу. Васино число оказалось в 2 раза больше, чем Димино, а Борино — на 2 больше, чем Гришино. Какое число написала Аня?",{},"B","Кто написал шестёрку?",[["Проверь удвоение","Дима и Вася могли написать 3 и 6 или 4 и 8 соответственно. Если убрать 3 и 6, среди 1, 4 и 8 нет двух чисел с разностью 2."],["Раздай остальные числа","Значит, у Димы 4, а у Васи 8. Гриша написал 1, а Боря 3. Ане досталось оставшееся число 6."]],""],[848,68,"",{"0":[51.7,34.1,31.4,26.3],"1":[201.7,34.1,31.1,26.3],"2":[351.6,34.1,31.4,26.3],"3":[501.5,34.1,28.4,26.3],"4":[651.3,34.1,31.7,26.3]},"C","Тысяча дециметров",[["Вспомни единицу","В одном метре 10 дециметров."],["Раздели на десять","В 1000 дециметрах ровно 1000 : 10 = 100 метров."]],""],[848,124,"С первого января 2015 года малыш Федя начал вести дневник. Он уверен, что в каждом месяце ровно 30 дней. Какую дату он напишет в своем дневнике 19 марта 2015 года в день конкурса «Кенгуру»?",{"0":[51.7,90.4,31.4,26.3],"1":[201.7,90.4,31.1,26.3],"2":[351.6,90.4,31.4,26.3],"3":[501.4,90.4,28.4,26.3],"4":[651.3,90.4,31.7,26.3]},"B","Дневник Феди",[["Сравни два начала марта","В календаре январь и февраль 2015 года вместе занимают 31 + 28 = 59 дней. У Феди они занимают 30 + 30 = 60 дней."],["Передвинь дату","Федин март начинается на день позднее. Поэтому в день 19 марта по календарю он напишет 18 марта."]],""],[848,177,"Маша хочет разрезать по сторонам клеточек прямоугольник 4×3 так, чтобы из полученных частей можно было сложить фигурку, изображённую справа. На какое наименьшее число частей придётся разрезать прямоугольник?",{"0":[51.7,143.7,31.4,26.3],"1":[161.7,143.7,31.1,26.3],"2":[278.3,143.7,31.4,26.3],"3":[395,143.7,28.4,26.3],"4":[501.5,143.7,31.7,26.3]},"B","Разрезаем прямоугольник",[["Подбери три детали","У фигурки отдели верхний уголок из трёх клеток и полоску из трёх клеток под ним слева. Останется деталь из шести клеток. Для таких деталей в прямоугольнике отложи три правые клетки верхнего ряда для полоски, а в правом нижнем углу отрежь уголок из трёх клеток."],["Почему двух мало?","Верхняя клетка и обе нижние ножки отстоят на пять рядов, поэтому при двух деталях окажутся в разных частях. Крайняя левая клетка соседствует с одной-единственной клеткой. Через ту же клетку верхушка соединяется с остальной фигурой, поэтому левый выступ тоже относится к верхней части. Правый выступ тогда должен быть у нижней части, иначе верхняя часть растянется на пять столбцов."],["Проверь нижнюю деталь","Она занимает четыре столбца и три ряда, как весь прямоугольник. В ней есть выемка между ножками и пустое место под правым выступом. Эти пустые места разделены клетками детали, поэтому закрыть оба одной связной частью нельзя."]],""],[848,151,"Вася наклеил на лист бумаги одну за другой 5 круглых наклеек с цифрами. В каком порядке он не мог их наклеивать?",{"0":[51.7,90.4,31.4,26.3],"1":[268.3,90.4,31.1,26.3],"2":[501.5,90.4,31.4,26.3],"3":[51.7,117.5,28.4,26.3],"4":[268.3,117.5,31.6,26.3]},"C","Порядок наклеек",[["Проверь перекрытие","Если наклейка закрывает часть соседней, её приклеили позже. Посмотри на границу наклеек 1 и 2."],["Проверь вариант В","Наклейка 1 лежит поверх наклейки 2, значит, наклейка 2 была раньше. В порядке 3, 5, 1, 2, 4 они стоят наоборот."]],""],[841,208,"Друзья выясняли, какой сегодня день недели. Витя сказал: «Вчера было воскресенье». Сема сказал: «Завтра будет суббота». Петя сказал: «Позавчера была пятница». Саша сказал: «Послезавтра будет среда». Двое из них ошиблись. Какой сегодня день недели?",{"0":[51.7,173.9,31.4,26.3],"1":[255,173.9,31.1,26.3],"2":[404.9,173.9,31.4,26.3],"3":[528.2,173.9,28.4,26.3],"4":[664.7,173.9,31.7,26.3]},"A","День недели",[["Переведи высказывания","Если вчера было воскресенье, сегодня понедельник. Если завтра суббота, сегодня пятница. Если позавчера была пятница, сегодня воскресенье."],["Найди совпадение","Если послезавтра среда, сегодня понедельник. Только понедельник назвали двое — Витя и Саша."]],""],[841,102,"Какой из результатов самый маленький?",{"0":[51.7,36.4,30.4,26.3],"1":[294.9,36.4,30.1,26.3],"2":[528.2,36.4,30.4,26.3],"3":[51.7,68.1,27.4,26.3],"4":[294.9,68.1,30.6,26.3]},"E","Наименьшее частное",[["Сравни делимые","Все выражения делят на 9. Значит, достаточно найти самую маленькую разность в скобках."],["Вычти","100 − 10 = 90 — меньше 100 − 1 и всех разностей, начинающихся с 1000. Подходит вариант Д."]],""],[841,176,"Наташа рассматривает в лупу разные части рисунка на школьной доске. Какое из изображений А–Д она не сможет увидеть?",{"0":[51.7,134.8,31.4,26.3],"1":[161.6,134.8,31.1,26.3],"2":[271.6,134.8,31.4,26.3],"3":[381.6,134.8,28.4,26.3],"4":[488.1,134.8,31.7,26.3]},"E","Вид через лупу",[["Найди нужное соединение","В варианте Д вертикальная линия идёт вверх от горизонтальной перекладины, а вниз от неё не продолжается. При этом горизонтальная линия тянется и влево, и вправо."],["Проверь рисунок","Вертикальные стороны большого квадрата идут и вверх, и вниз. Короткий вертикальный отрезок внутри него тоже пересекает среднюю линию насквозь. Вид Д нигде не получается."]],""],[841,98,"Разность двух чисел на 3 меньше уменьшаемого и на 4 больше вычитаемого. Чему она равна?",{"0":[51.7,63.5,31.4,26.3],"1":[201.7,63.5,31.1,26.3],"2":[351.6,63.5,31.4,26.3],"3":[501.5,63.5,28.4,26.3],"4":[651.3,63.5,31.7,26.3]},"A","Уменьшаемое и вычитаемое",[["Восстанови вычитаемое","Разность на 3 меньше уменьшаемого. Значит, из уменьшаемого вычли 3."],["Найди разность","Она на 4 больше вычитаемого, поэтому равна 3 + 4 = 7."]],""],[841,181,"Фигуру, изображённую на рис. 1, Вася разрезал на одинаковые треугольники, изображённые на рис. 2. Сколько треугольников у него получилось?",{"0":[51.7,117.5,31.4,26.3],"1":[201.7,117.5,31.1,26.3],"2":[351.6,117.5,31.4,26.3],"3":[51.7,146.9,28.4,26.3],"4":[201.7,146.9,31.7,26.3]},"D","Разрезание на треугольники",[["Раздели середину","В середине фигуры три квадрата размером 2 × 2. Если провести обе диагонали в каждом, получится по четыре треугольника с рисунка 2."],["Посчитай выступы","Выступ слева делится на два таких треугольника, выступ справа уже имеет нужную форму. Всего 3 × 4 + 2 + 1 = 15."]],""],[841,181,"Стрелочки на рисунке указывают на результаты действий с числами. Числа 1, 2, 3, 4, 5, 6 и 7 надо разместить по одному в квадратиках так, чтобы все результаты были правильными. Какое число попадёт в заштрихованный квадратик?",{"0":[51.7,146.8,31.4,26.3],"1":[161.7,146.8,31.1,26.3],"2":[278.2,146.8,31.4,26.3],"3":[395,146.8,28.4,26.3],"4":[501.4,146.8,31.7,26.3]},"A","Числа в квадратиках",[["Начни с умножения","Единица множителем быть не может: результат повторил бы другой множитель. Из разных чисел больше 1 только 2 × 3 даёт результат не больше 7. Значит, слева в сумме стоит 6."],["Посмотри на сумму","Чтобы прибавить к 6 число и получить не больше 7, надо прибавить 1. В заштрихованном квадратике поэтому стоит 1. Это согласуется с вычитанием 5 − 4."]],""],[841,134,"Фигура на рисунке состоит из одинаковых квадратов со стороной 1 см. Чему равен её периметр?",{"0":[51.7,65.7,31.4,26.3],"1":[201.7,65.7,31.1,26.3],"2":[351.6,65.7,31.4,26.3],"3":[501.4,65.7,28.4,26.3],"4":[51.6,97.4,31.7,26.3]},"D","Периметр ступенчатой фигуры",[["Сосчитай горизонтальные края","Нижний край равен 3 см. Выше фигура сужается, и все горизонтальные ступеньки сверху вместе дают те же 3 см."],["Сосчитай вертикальные края","Слева край поднимается на три ряда, справа спускается на три ряда. Это ещё 6 см. Периметр 3 + 3 + 6 = 12 см."]],""],[848,179,"Маша заполняет горшочек крупой. Он будет полным, если в него насыпать 6 чайных ложек, 3 десертных и 1 столовую ложку крупы или 2 чайные ложки, 1 десертную и 3 столовые ложки той же крупы. У Маши есть только столовые ложки. Сколько таких ложек крупы ей придется насыпать?",{"0":[51.7,144.7,31.4,26.3],"1":[201.7,144.7,31.1,26.3],"2":[351.6,144.7,31.4,26.3],"3":[501.5,144.7,28.4,26.3],"4":[651.5,144.7,31.7,26.3]},"A","Три вида ложек",[["Сократи общую часть","Оба набора наполняют один горшочек. Убери из обоих по 2 чайные, 1 десертной и 1 столовой ложке. Останутся 4 чайные и 2 десертные с одной стороны и 2 столовые с другой."],["Замени маленькие ложки","Значит, 2 чайные и 1 десертная вместе равны 1 столовой. Во втором наборе к ним добавили ещё 3 столовые ложки, всего 4."]],""],[848,241,"У длинной верёвки связали концы и разложили получившуюся петлю на столе. Часть этой петли закрыта (смотри рисунок). Как может выглядеть закрытая часть?",{"0":[51.7,145.5,31.4,26.3],"1":[245,145.5,31.1,26.3],"2":[445,145.5,31.4,26.3],"3":[51.7,207.3,28.4,26.3],"4":[245,207.3,31.7,26.3]},"C","Одна петля верёвки",[["Пронумеруй концы","Над краем прямоугольника видно шесть концов. Если считать слева, открытые дуги соединяют 1 с 4, 2 с 6 и 3 с 5."],["Проследи всю петлю","В варианте В скрытые дуги соединяют 1 с 2, 3 с 6 и 4 с 5. Тогда путь 1 → 4 → 5 → 3 → 6 → 2 → 1 проходит через все шесть концов одной петли."]],""],[848,124,"В гостях у бабушки Женя и Лена ели мороженое ежедневно: каждая по 2 или 3 стаканчика. Всего Женя съела 25 стаканчиков, а Лена — 19. Сколько дней они гостили у бабушки?",{"0":[51.8,90.5,31.4,26.3],"1":[201.8,90.5,31.1,26.3],"2":[351.7,90.5,31.4,26.3],"3":[501.6,90.5,28.4,26.3],"4":[651.5,90.5,31.7,26.3]},"B","Мороженое у бабушки",[["Проверь Женю","За 8 дней даже по три стаканчика в день Женя съела бы только 24. Её 25 стаканчиков требуют хотя бы 9 дней."],["Проверь Лену","За 10 дней даже по два стаканчика в день Лена съела бы 20. Значит, её 19 стаканчиков требуют не больше 9 дней. Вместе получается ровно 9. За девять дней Женя могла съесть по три стаканчика семь раз и по два ещё два раза, а Лена — только один раз три и восемь раз по два."]],""],[848,125,"В числовом ребусе буквами O, D, E, V, N обозначены разные цифры. Сколько различных цифр может обозначать буква V?",{"0":[51.7,90.5,31.4,26.3],"1":[161.7,90.5,31.1,26.3],"2":[278.3,90.5,31.4,26.3],"3":[395,90.5,28.4,26.3],"4":[501.5,90.5,31.7,26.3]},"B","Ребус ODD + ODD",[["Найди сотни и тысячи","Сумма двух трёхзначных чисел не больше 1998. Значит, первая цифра E равна 1, и в разряде десятков тоже стоит 1."],["Найди последние цифры","В десятках 2 × D вместе с переносом должно оканчиваться на 1. Поэтому перенос из единиц равен 1, D = 5, а N = 0."],["Проверь разряд сотен","Если O равно 6, 7, 8 или 9, то 2 × O + 1 даёт 13, 15, 17 или 19. Цифры V = 5 и V = 9 повторили бы уже поставленные цифры. Подходят только V = 3 и V = 7."]],""],[848,152,"Дима, Федя, Надя и Катя пошли в лес за грибами. Известно, что Дима нашел грибов меньше, чем Федя, мальчики нашли грибов столько же, сколько девочки, а Дима и Надя нашли грибов больше, чем Федя и Катя. Кто нашел больше всех грибов?",{"0":[51.8,117.6,31.4,26.3],"1":[165.2,117.6,31.1,26.3],"2":[278.3,117.6,31.4,26.3],"3":[388.3,117.6,28.4,26.3],"4":[491.5,117.6,31.7,26.3]},"D","Кто нашёл больше грибов?",[["Сравни пары","Дима и Надя нашли больше половины всех грибов, ведь у них вместе больше, чем у Феди и Кати. Дима и Федя вместе нашли ровно половину."],["Проверь остальных","Если из обоих количеств убрать грибы Димы, видно, что Надя обошла Федю, а значит, и Диму. При этом по условию девочки вместе собрали столько же, сколько мальчики: чтобы Надя нашла больше Феди, Катя должна была найти меньше Димы."]],""],[848,125,"Никита выписывает подряд целые числа 1, 2, 3,…, но он не любит цифру 7 и пропускает все числа, которые её содержат. Он выписал 777 чисел. Какое число он написал последним?",{"0":[51.8,90.5,31.4,26.3],"1":[201.8,90.5,31.1,26.3],"2":[351.7,90.5,31.4,26.3],"3":[501.5,90.5,28.4,26.3],"4":[651.4,90.5,31.7,26.3]},"C","Числа без семёрки",[["Посчитай до 999","В каждой из трёх позиций есть 9 разрешённых цифр. Получается 9 × 9 × 9 = 729 записей, включая 000. Положительных чисел 728."],["Дойди до нужной записи","Осталось 777 − 728 = 49 чисел. С 1000 по 1049 в каждом десятке пропускаем одно число с 7, поэтому выписываем 45. Ещё четыре числа — 1050, 1051, 1052 и 1053."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2015":{"1":{"question":"Незнайка писал слово КЕНГУРУ. У него получилось: Сколько букв он написал неправильно?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-01.webp","imageWidth":366,"imageHeight":66},"2":{"question":"Чему равна сумма двадцати сотен и пятнадцати?","choices":["35","215","2015","20015","200015"]},"3":{"question":"Индеец Белый Орёл живет в вигваме, на котором треугольников и квадратиков нарисовано поровну. На каком из рисунков изображён его вигвам?","image":"assets/legacy-conditions/2015/task-03.webp","imageWidth":922,"imageHeight":187},"4":{"question":"Что не равно 12?","choices":["дюжина","число месяцев в году","число часов в сутках","утроенный номер этой задачи","число подвигов Геракла"]},"5":{"question":"На рисунке изображён пруд и несколько лягушек. Сколько из этих лягушек сидят в пруду?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2015/task-05.webp","imageWidth":343,"imageHeight":267},"6":{"question":"В числе 2015 четыре цифры. Произведение двух бóльших цифр поделили на сумму двух меньших. Что получилось?","choices":["6","7","8","10","15"]},"7":{"question":"Петя катается на велосипеде по дорожкам, изображённым на рисунке. Он стартует из точки О в направлении, указанном стрелкой. На первом перекрёстке Петя поворачивает направо, на втором — налево, потом опять направо, потом опять налево, и так далее. В какой точке он не может оказаться?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2015/task-07.webp","imageWidth":332,"imageHeight":287},"8":{"question":"Аня отметила на прямой линии 5 красных точек. В каждый промежуток между красными точками она поставила синюю точку, а потом в каждый промежуток между красной и синей точками — зелёную точку. Сколько всего точек получилось?","choices":["9","15","17","18","20"]},"9":{"question":"Аня, Боря, Вася, Гриша и Дима написали на доске числа 1, 3, 4, 6 и 8, каждый по одному числу. Васино число оказалось в 2 раза больше, чем Димино, а Борино — на 2 больше, чем Гришино. Какое число написала Аня?","choices":["8","6","4","3","1"]},"10":{"question":"Тысяча дециметров равна","choices":["10 км","1 км","100 м","10 м","1 м"]},"11":{"question":"С первого января 2015 года малыш Федя начал вести дневник. Он уверен, что в каждом месяце ровно 30 дней. Какую дату он напишет в своем дневнике 19 марта 2015 года в день конкурса «Кенгуру»?","choices":["17 марта","18 марта","19 марта","20 марта","21 марта"]},"12":{"question":"Маша хочет разрезать по сторонам клеточек прямоугольник 4×3 так, чтобы из полученных частей можно было сложить фигурку, изображённую справа. На какое наименьшее число частей придётся разрезать прямоугольник?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2015/task-12.svg","imageWidth":220,"imageHeight":219},"13":{"question":"Вася наклеил на лист бумаги одну за другой 5 круглых наклеек с цифрами. В каком порядке он не мог их наклеивать?","choices":["3, 2, 5, 4, 1","5, 3, 4, 2, 1","3, 5, 1, 2, 4","5, 3, 2, 4, 1","3, 2, 1, 5, 4"],"image":"assets/legacy-conditions/2015/task-13.webp","imageWidth":313,"imageHeight":86},"14":{"question":"Друзья выясняли, какой сегодня день недели. Витя сказал: «Вчера было воскресенье». Сема сказал: «Завтра будет суббота». Петя сказал: «Позавчера была пятница». Саша сказал: «Послезавтра будет среда». Двое из них ошиблись. Какой сегодня день недели?","choices":["понедельник","вторник","среда","четверг","суббота"]},"15":{"question":"Какой из результатов самый маленький?","choices":["(100 − 1): 9","(1000 − 10): 9","(1000 − 1): 9","(1000 − 100): 9","(100 − 10): 9"]},"16":{"question":"Наташа рассматривает в лупу разные части рисунка на школьной доске. Какое из изображений А–Д она не сможет увидеть?","image":"assets/legacy-conditions/2015/task-16.webp","imageWidth":958,"imageHeight":223},"17":{"question":"Разность двух чисел на 3 меньше уменьшаемого и на 4 больше вычитаемого. Чему она равна?","choices":["7","9","10","12","15"]},"18":{"question":"Фигуру, изображённую на рис. 1, Вася разрезал на одинаковые треугольники, изображённые на рис. 2. Сколько треугольников у него получилось?","choices":["8","12","14","15","16"],"image":"assets/legacy-conditions/2015/task-18.webp","imageWidth":381,"imageHeight":197},"19":{"question":"Стрелочки на рисунке указывают на результаты действий с числами. Числа 1, 2, 3, 4, 5, 6 и 7 надо разместить по одному в квадратиках так, чтобы все результаты были правильными. Какое число попадёт в заштрихованный квадратик?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-19.webp","imageWidth":259,"imageHeight":208},"20":{"question":"Фигура на рисунке состоит из одинаковых квадратов со стороной 1 см. Чему равен её периметр?","choices":["9 см","10 см","11 см","12 см","невозможно определить"],"image":"assets/legacy-conditions/2015/task-20.svg","imageWidth":220,"imageHeight":217},"21":{"question":"Маша заполняет горшочек крупой. Он будет полным, если в него насыпать 6 чайных ложек, 3 десертных и 1 столовую ложку крупы или 2 чайные ложки, 1 десертную и 3 столовые ложки той же крупы. У Маши есть только столовые ложки. Сколько таких ложек крупы ей придется насыпать?","choices":["4","5","6","7","8"]},"22":{"question":"У длинной верёвки связали концы и разложили получившуюся петлю на столе. Часть этой петли закрыта (смотри рисунок). Как может выглядеть закрытая часть?","image":"assets/legacy-conditions/2015/task-22.webp","imageWidth":963,"imageHeight":305},"23":{"question":"В гостях у бабушки Женя и Лена ели мороженое ежедневно: каждая по 2 или 3 стаканчика. Всего Женя съела 25 стаканчиков, а Лена — 19. Сколько дней они гостили у бабушки?","choices":["8","9","10","11","12"]},"24":{"question":"В числовом ребусе буквами O, D, E, V, N обозначены разные цифры. Сколько различных цифр может обозначать буква V?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-24.svg","imageWidth":209,"imageHeight":220},"25":{"question":"Дима, Федя, Надя и Катя пошли в лес за грибами. Известно, что Дима нашел грибов меньше, чем Федя, мальчики нашли грибов столько же, сколько девочки, а Дима и Надя нашли грибов больше, чем Федя и Катя. Кто нашел больше всех грибов?","choices":["Дима","Федя","Катя","Надя","невозможно определить"]},"26":{"question":"Никита выписывает подряд целые числа 1, 2, 3,…, но он не любит цифру 7 и пропускает все числа, которые её содержат. Он выписал 777 чисел. Какое число он написал последним?","choices":["888","1000","1053","1333","1631"]}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'assets/kenguru';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, figure) {
    const [url, w, h] = figure;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="16 21 65 62" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, figure) {
    const [url, w, h] = figure;
    const sources = [[7, 43], [57, 57], [123, 60], [193, 56], [253, 53], [313, 62], [380, 58]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      const letterWidth = sw * 77 / 100;
      drawing += crop(url, w, h, [sx, 3, sw, 100], x + (85 - letterWidth) / 2, 30, letterWidth, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask?.question ? authoredTask : imported ?? authoredTask;
      const figure = native === imported && imported?.image
        ? [imported.image, imported.imageWidth, imported.imageHeight] : null;
      const illustration = figure
        ? svg(imported.imageWidth, imported.imageHeight, authoredTask?.illustration ?? 'Рисунки и варианты из условия',
            image(escape(imported.image), imported.imageWidth, imported.imageHeight))
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: figure?.[0],
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask?.crop) {
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, figure ?? card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers${[2017, 2018].includes(year) ? '-reviewed' : ''}.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

register((globalThis.KENGURU_ARCHIVE["2015-3-4"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2015] ?? []).find(edition => edition.id === "2015-3-4")), globalThis.KENGURU_CHOICE_LAYOUTS, {"2015-3-4/3":["На вигваме сверху треугольники остриём влево. Ниже слева ещё два треугольника, а справа — квадратики.","Наверху вигвама один квадратик. Под ним два треугольника, а у основания по квадратику с каждой стороны входа.","В верхней части вигвама квадратики идут от вершины к правому краю. Снизу три треугольника — влево, вниз и вправо.","Под вершиной вигвама треугольник остриём вверх. Посередине квадрат слева и треугольник справа, внизу — треугольник слева и квадрат справа.","Под вершиной вигвама треугольник остриём вправо. Под ним треугольник слева и квадратик справа. Внизу слева ещё треугольник, справа — два квадратика."],"2015-3-4/16":["Через круг идёт диагональ сверху слева вниз направо. От её середины к нижнему краю отходит вертикальная линия.","Вертикальная линия пересекает весь круг. От её середины влево до края идёт горизонтальная линия.","Три линии идут из центра круга к его краю влево, вниз и по диагонали вниз-влево.","Горизонтальная и вертикальная линии пересекаются в центре и делят круг на четыре части.","Горизонтальная линия пересекает весь круг. От её середины к верхнему краю отходит вертикальная линия."],"2015-3-4/22":["Из шести концов, считая слева, соединены первый с третьим, второй с шестым и четвёртый с пятым. Дуга от второго к шестому проходит поверх дуги от первого к третьему.","Из шести концов, считая слева, соединены первый с четвёртым, второй с шестым и третий с пятым. Дуга от первого к четвёртому проходит поверх длинной дуги и под дугой от третьего к пятому.","Слева малая отдельная дуга соединяет первый и второй концы. Справа большая дуга идёт от третьего к шестому, внутри неё малая от четвёртого к пятому.","Слева малая отдельная дуга соединяет первый и второй концы. Справа дуга от четвёртого к шестому пересекает и перекрывает дугу от третьего к пятому.","Слева большая дуга идёт от первого конца к четвёртому, внутри неё малая от второго к третьему. Справа отдельная дуга соединяет пятый и шестой концы."]});
